customElements.define('range-slider',class extends HTMLElement{constructor(){super();this.unitDefaultLabel=this.getAttribute('unit-default-label')||'';this.unitPluralLabel=this.getAttribute('unit-plural-label')||`${this.unitDefaultLabel}s`;this.unitMaxLabel=this.getAttribute('unit-max-label')||'all';this.isDragging=!1;this.startDragOffsetX=0;this.maxRange=0;this.lastEmittedValues={min:0,max:0};this.acceptedKeys=["Enter","Backspace","ArrowUp","ArrowDown","Delete","Space"];this.maximumValue=parseInt(this.getAttribute('max'))||null;this.minimumValue=parseInt(this.getAttribute('min'))||null}
connectedCallback(){this.setupComponent()}
disconnectedCallback(){this.clearListeners()}
clearListeners(){document.removeEventListener('mousemove',this.handleMouseMove);document.removeEventListener('mouseup',this.handleMouseUp)}
setupComponent(){this.sliderElement=this.querySelector('.range .slider');this.fillElement=this.sliderElement.querySelector('.fill');this.minNumInputElement=this.querySelector("input[type='number'].min-range");this.maxNumInputElement=this.querySelector("input[type='number'].max-range");if(this.minNumInputElement)
this.lastEmittedValues.min=this.minNumInputElement.value;if(this.maxNumInputElement)
this.lastEmittedValues.max=this.maxNumInputElement.value;this.minRangeInputElement=this.querySelector(".range input[type='range'].min-input");this.maxRangeInputElement=this.querySelector(".range input[type='range'].max-input");this.rangeOutputElement=this.querySelector(".range-output");this.setupMinMaxValues();this.setupListeners()}
setupMinMaxValues(){if(this.maximumValue!==null&&this.minimumValue!==null){if(this.minNumInputElement){this.minNumInputElement.min=this.minimumValue;this.minNumInputElement.max=this.maximumValue}
if(this.maxNumInputElement){this.maxNumInputElement.min=this.minimumValue;this.maxNumInputElement.max=this.maximumValue}
if(this.minRangeInputElement){this.minRangeInputElement.min=this.minimumValue;this.minRangeInputElement.max=this.maximumValue}
if(this.maxRangeInputElement){this.maxRangeInputElement.min=this.minimumValue;this.maxRangeInputElement.max=this.maximumValue}
this.maxRange=parseInt(this.maximumValue)-parseInt(this.minimumValue)}}
setupListeners(){this.clearListeners();this.minNumInputElement.addEventListener('input',(e)=>{this.updateRange(e)});this.maxNumInputElement.addEventListener('input',(e)=>{this.updateRange(e)});this.minRangeInputElement.addEventListener('input',()=>{if(parseInt(this.minRangeInputElement.value)>=parseInt(this.maxRangeInputElement.value)){this.maxRangeInputElement.value=this.minRangeInputElement.value}
this.updateFill()});this.maxRangeInputElement.addEventListener('input',()=>{if(parseInt(this.maxRangeInputElement.value)<=parseInt(this.minRangeInputElement.value)){this.minRangeInputElement.value=this.maxRangeInputElement.value}
this.updateFill()});this.fillElement.addEventListener('mousedown',(e)=>{this.startSliderDrag(e)});this.handleMouseMove=(e)=>this.updateSliderDrag(e);this.handleMouseUp=()=>this.endSliderDrag();document.addEventListener('mousemove',this.handleMouseMove);document.addEventListener('mouseup',this.handleMouseUp);this.updateFill()}
startSliderDrag(e){e.preventDefault();this.isDragging=!0;this.startDragOffsetX=e.clientX-this.fillElement.getBoundingClientRect().left;this.classList.toggle('dragging',this.isDragging)}
updateSliderDrag(e){if(this.isDragging){const sliderRect=this.sliderElement.getBoundingClientRect();const fillWidth=parseFloat(this.fillElement.style.width||0);let newLeft=((e.clientX-sliderRect.left-this.startDragOffsetX)/sliderRect.width)*100;newLeft=Math.min(Math.max(newLeft,0),100-fillWidth);this.fillElement.style.left=`${newLeft}%`;const inputRange=this.maxRangeInputElement.max-this.minRangeInputElement.min;const newMin=Math.round((newLeft/100)*inputRange)+parseInt(this.minRangeInputElement.min);const newMax=newMin+parseInt(this.maxRangeInputElement.value)-parseInt(this.minRangeInputElement.value);this.minRangeInputElement.value=newMin;this.maxRangeInputElement.value=newMax;this.updateFill()}
this.classList.toggle('dragging',this.isDragging)}
endSliderDrag(){if(this.isDragging){this.isDragging=!1;this.emitChangeEvent()}
this.classList.toggle('dragging',this.isDragging)}
updateFill(){const minValue=parseInt(this.minRangeInputElement.value);const maxValue=parseInt(this.maxRangeInputElement.value);const totalRange=this.maxRangeInputElement.max-this.minRangeInputElement.min;const valueRange=maxValue-minValue;const fillWidth=Math.floor((valueRange/totalRange)*100);const leftOffset=Math.floor(((minValue-this.minRangeInputElement.min)/totalRange)*100);this.fillElement.style.width=`${fillWidth}%`;this.fillElement.style.left=`${leftOffset}%`;this.minNumInputElement.value=minValue;this.maxNumInputElement.value=maxValue;this.emitChangeEvent();this.updateOutputText(valueRange)}
updateRange(e){const inputElement=e.target;let minValue=parseInt(this.minNumInputElement.value);let maxValue=parseInt(this.maxNumInputElement.value);if(inputElement===this.minNumInputElement&&minValue>maxValue){maxValue=minValue;this.maxNumInputElement.value=maxValue}else if(inputElement===this.maxNumInputElement&&maxValue<minValue){minValue=maxValue;this.minNumInputElement.value=minValue}
this.minRangeInputElement.value=minValue;this.maxRangeInputElement.value=maxValue;this.updateFill()}
getNumberInputRangeValues(){return{min:parseInt(this.minNumInputElement.value),max:parseInt(this.maxNumInputElement.value)}}
updateOutputText(number){const outputText=(parseInt(number)===this.maxRange)?this.unitMaxLabel:`${number += 1} ${((number) > 1) ? this.unitPluralLabel : this.unitDefaultLabel }`;this.rangeOutputElement.textContent=outputText}
emitEvent(type,eventDetails={}){const event=new CustomEvent(`range-slider:${type}`,{bubbles:!0,cancellable:!1,detail:{id:this.id||this.getAttribute('name')||null,...eventDetails}});return this.dispatchEvent(event)}
emitChangeEvent(){if(!this.lastEmittedValues)
return;const rangeValues=this.getNumberInputRangeValues();if(parseInt(this.lastEmittedValues.min)!==parseInt(rangeValues.min)||parseInt(this.lastEmittedValues.max)!==parseInt(rangeValues.max)){this.lastEmittedValues.min=rangeValues.min;this.lastEmittedValues.max=rangeValues.max;this.emitEvent('change',{min:rangeValues.min,max:rangeValues.max})}}})